PHASE6E_MARKER = "# Phase 6E — Post-Launch Stabilization and Operational Assurance"
PHASE6F_MARKER = "# Phase 6F — Controlled Production Validation and Customer Pilot"
PHASE6G_MARKER = "# Phase 6G — Pilot Telemetry, Outcome Review, and Go/No-Go Decision"
PHASE6H_MARKER = "# Phase 6H — Controlled Rollout Governance and Launch Readiness"
PHASE6I_MARKER = "# Phase 6I — Rollout Observation, Exception Control, and Post-Launch Assurance"
PHASE6J_MARKER = "# Phase 6J — Service Transition, SLA Governance, and Operational Handoff"

PHASE6E_SOURCE = '\n# ============================================================================\n# Phase 6E — Post-Launch Stabilization and Operational Assurance\n# Safe, local-first operational controls. No external network calls are made.\n# ============================================================================\n\nPHASE6E_STATE_FILE = RECORDINGS_FOLDER / "phase6e_operational_state.json"\nPHASE6E_DRILLS_FILE = RECORDINGS_FOLDER / "phase6e_incident_drills.json"\nPHASE6E_SLO_FILE = RECORDINGS_FOLDER / "phase6e_slo_history.json"\nPHASE6E_DEPLOYMENTS_FILE = RECORDINGS_FOLDER / "phase6e_deployments.json"\n\nPHASE6E_DEFAULT_SLOS = {\n    "availability_target": 99.9,\n    "api_p95_ms_target": 750,\n    "camera_online_target": 95.0,\n    "recording_success_target": 99.0,\n    "upload_success_target": 98.0,\n    "max_open_incidents": 3,\n}\n\n\nclass Phase6EDeploymentCheckModel(BaseModel):\n    release_id: str = Field(min_length=2, max_length=120)\n    version: str = Field(min_length=1, max_length=60)\n    environment: str = Field(default="production", max_length=40)\n    notes: str = Field(default="", max_length=2000)\n\n\nclass Phase6EIncidentDrillModel(BaseModel):\n    scenario: str = Field(min_length=3, max_length=160)\n    owner: str = Field(min_length=2, max_length=120)\n    result: str = Field(default="passed", pattern="^(passed|failed|partial)$")\n    recovery_minutes: int = Field(default=0, ge=0, le=10080)\n    notes: str = Field(default="", max_length=3000)\n\n\ndef _phase6e_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef phase6e_operational_snapshot() -> dict:\n    now = datetime.now()\n    total_cameras = max(1, CAMERA_COUNT)\n    online_cameras = sum(\n        1 for camera in camera_process_state.values()\n        if camera.get("live") in {"online", "running", "healthy"}\n    )\n    recording_cameras = sum(\n        1 for camera in camera_process_state.values()\n        if camera.get("recording") in {"online", "running", "healthy"}\n    )\n\n    queue = globals().get("cloud_upload_queue", [])\n    uploaded = sum(item.get("status") == "uploaded" for item in queue)\n    failed = sum(item.get("status") == "failed" for item in queue)\n    completed_uploads = uploaded + failed\n    upload_success = round((uploaded / completed_uploads) * 100, 2) if completed_uploads else 100.0\n\n    incidents = _phase6e_load(INCIDENTS_FILE, [])\n    open_incidents = sum(\n        str(item.get("status", "open")).lower() not in {"resolved", "closed"}\n        for item in incidents\n    )\n\n    uptime_seconds = max(0, int((now - STARTED_AT).total_seconds()))\n    camera_online_percent = round((online_cameras / total_cameras) * 100, 2)\n    recording_success_percent = round((recording_cameras / total_cameras) * 100, 2)\n\n    checks = {\n        "application_running": True,\n        "release_candidate": bool(RELEASE_CANDIDATE),\n        "secure_cookies": bool(SECURE_COOKIES),\n        "https_enforced": bool(FORCE_HTTPS),\n        "public_url_configured": bool(PUBLIC_BASE_URL),\n        "backup_directory_available": BACKUPS_FOLDER.exists(),\n        "recordings_directory_writable": os.access(RECORDINGS_FOLDER, os.W_OK),\n        "camera_online_percent": camera_online_percent,\n        "recording_success_percent": recording_success_percent,\n        "upload_success_percent": upload_success,\n        "open_incidents": open_incidents,\n    }\n\n    targets = dict(PHASE6E_DEFAULT_SLOS)\n    evaluations = {\n        "camera_online": camera_online_percent >= targets["camera_online_target"],\n        "recording_success": recording_success_percent >= targets["recording_success_target"],\n        "upload_success": upload_success >= targets["upload_success_target"],\n        "incident_load": open_incidents <= targets["max_open_incidents"],\n    }\n    healthy = all(evaluations.values())\n\n    return {\n        "phase": "6E",\n        "name": "Post-Launch Stabilization and Operational Assurance",\n        "checked_at": now.isoformat(),\n        "uptime_seconds": uptime_seconds,\n        "healthy": healthy,\n        "checks": checks,\n        "targets": targets,\n        "evaluations": evaluations,\n        "recommended_action": (\n            "Continue normal operations and review the dashboard daily."\n            if healthy\n            else "Review failed SLO checks, open incidents, and rollback readiness."\n        ),\n    }\n\n\ndef phase6e_release_readiness(release_id: str, version: str, environment: str, notes: str) -> dict:\n    snapshot = phase6e_operational_snapshot()\n    cloud_snapshot_fn = globals().get("cloud_configuration_snapshot")\n    cloud = cloud_snapshot_fn() if callable(cloud_snapshot_fn) else {}\n\n    blockers = []\n    if environment.lower() == "production":\n        if not SECURE_COOKIES:\n            blockers.append("Secure cookies are disabled.")\n        if not FORCE_HTTPS:\n            blockers.append("HTTPS enforcement is disabled.")\n        if not PUBLIC_BASE_URL:\n            blockers.append("Public base URL is not configured.")\n    if not snapshot["checks"]["recordings_directory_writable"]:\n        blockers.append("Recordings directory is not writable.")\n    if not snapshot["checks"]["backup_directory_available"]:\n        blockers.append("Backup directory is unavailable.")\n    if snapshot["checks"]["open_incidents"] > PHASE6E_DEFAULT_SLOS["max_open_incidents"]:\n        blockers.append("Open incident count exceeds the Phase 6E limit.")\n\n    warnings = []\n    if not RELEASE_CANDIDATE:\n        warnings.append("Build is not marked as a release candidate.")\n    if cloud and not cloud.get("cloud_foundation_ready", False):\n        warnings.append("Cloud foundation configuration is incomplete.")\n    if snapshot["checks"]["camera_online_percent"] < PHASE6E_DEFAULT_SLOS["camera_online_target"]:\n        warnings.append("Camera online percentage is below target.")\n\n    record = {\n        "id": uuid.uuid4().hex[:16],\n        "release_id": release_id.strip(),\n        "version": version.strip(),\n        "environment": environment.strip().lower(),\n        "notes": notes.strip(),\n        "created_at": datetime.now().isoformat(),\n        "status": "blocked" if blockers else ("warning" if warnings else "ready"),\n        "blockers": blockers,\n        "warnings": warnings,\n        "rollback_ready": bool(BACKUPS_FOLDER.exists() and os.access(BACKUPS_FOLDER, os.W_OK)),\n        "snapshot": snapshot,\n    }\n    records = _phase6e_load(PHASE6E_DEPLOYMENTS_FILE, [])\n    records.append(record)\n    save_json_file(PHASE6E_DEPLOYMENTS_FILE, records[-500:])\n    structured_log(\n        "phase6e.release_readiness",\n        release_id=record["release_id"],\n        status=record["status"],\n        blocker_count=len(blockers),\n        warning_count=len(warnings),\n    )\n    return record\n\n\n@app.get("/api/operations/stability")\ndef phase6e_stability_api(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    snapshot = phase6e_operational_snapshot()\n    history = _phase6e_load(PHASE6E_SLO_FILE, [])\n    history.append({\n        "checked_at": snapshot["checked_at"],\n        "healthy": snapshot["healthy"],\n        "checks": snapshot["checks"],\n        "evaluations": snapshot["evaluations"],\n    })\n    save_json_file(PHASE6E_SLO_FILE, history[-2016:])\n    return snapshot\n\n\n@app.get("/api/operations/deployments")\ndef phase6e_deployments_api(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    records = _phase6e_load(PHASE6E_DEPLOYMENTS_FILE, [])\n    return {"deployments": list(reversed(records[-100:]))}\n\n\n@app.post("/api/operations/deployments/check")\ndef phase6e_deployment_check(payload: Phase6EDeploymentCheckModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    return phase6e_release_readiness(\n        payload.release_id, payload.version, payload.environment, payload.notes\n    )\n\n\n@app.get("/api/operations/drills")\ndef phase6e_drills_api(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    return {"drills": list(reversed(_phase6e_load(PHASE6E_DRILLS_FILE, [])[-100:]))}\n\n\n@app.post("/api/operations/drills")\ndef phase6e_create_drill(payload: Phase6EIncidentDrillModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    drill = {\n        "id": uuid.uuid4().hex[:16],\n        "scenario": payload.scenario.strip(),\n        "owner": payload.owner.strip(),\n        "result": payload.result,\n        "recovery_minutes": payload.recovery_minutes,\n        "notes": payload.notes.strip(),\n        "created_at": datetime.now().isoformat(),\n        "created_by": user.get("id", "unknown"),\n    }\n    drills = _phase6e_load(PHASE6E_DRILLS_FILE, [])\n    drills.append(drill)\n    save_json_file(PHASE6E_DRILLS_FILE, drills[-500:])\n    structured_log(\n        "phase6e.incident_drill",\n        drill_id=drill["id"],\n        result=drill["result"],\n        recovery_minutes=drill["recovery_minutes"],\n    )\n    return {"status": "complete", "message": "Incident drill recorded.", "drill": drill}\n\n\n@app.get("/operations/stability", response_class=HTMLResponse)\ndef phase6e_stability_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    content = """\n    <header class="topbar">\n      <div><p class="eyebrow">Phase 6E operations</p><h1>Stability and release assurance</h1></div>\n      <button class="action-button" id="refresh-phase6e">Refresh checks</button>\n    </header>\n    <section class="site-summary-grid" id="phase6e-summary"></section>\n    <section class="panel">\n      <div class="panel-head"><div><h2>Release readiness</h2><div class="health-detail">Local validation only. This does not deploy or contact an external service.</div></div></div>\n      <form id="phase6e-release-form" class="settings-grid">\n        <label>Release ID<input id="phase6e-release-id" required placeholder="release-2026-08-04"></label>\n        <label>Version<input id="phase6e-version" required placeholder="1.0.0"></label>\n        <label>Environment<select id="phase6e-environment"><option value="production">Production</option><option value="staging">Staging</option></select></label>\n        <label>Notes<textarea id="phase6e-notes" rows="3"></textarea></label>\n        <div><button class="action-button" type="submit">Run readiness check</button></div>\n      </form>\n      <div id="phase6e-release-result" class="health-detail" style="margin-top:14px"></div>\n    </section>\n    <section class="panel">\n      <div class="panel-head"><h2>Incident drill log</h2></div>\n      <form id="phase6e-drill-form" class="settings-grid">\n        <label>Scenario<input id="phase6e-scenario" required placeholder="S3 upload queue unavailable"></label>\n        <label>Owner<input id="phase6e-owner" required placeholder="Operations"></label>\n        <label>Result<select id="phase6e-result"><option>passed</option><option>partial</option><option>failed</option></select></label>\n        <label>Recovery minutes<input id="phase6e-recovery" type="number" min="0" value="0"></label>\n        <label>Notes<textarea id="phase6e-drill-notes" rows="3"></textarea></label>\n        <div><button class="action-button" type="submit">Record drill</button></div>\n      </form>\n      <div id="phase6e-drills" style="margin-top:18px"></div>\n    </section>\n    """\n    scripts = """\n    <script>\n    const p6eEsc=value=>String(value??\'\').replace(/[&<>"\']/g,ch=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[ch]));\n    async function phase6eLoad(){\n      const response=await fetch(\'/api/operations/stability\'), data=await response.json();\n      if(!response.ok){showToast(data.detail||\'Could not load stability checks.\');return;}\n      const checks=data.checks||{};\n      document.getElementById(\'phase6e-summary\').innerHTML=[\n        [\'Overall\',data.healthy?\'Healthy\':\'Needs attention\'],\n        [\'Camera online\',`${checks.camera_online_percent??0}%`],\n        [\'Recording\',`${checks.recording_success_percent??0}%`],\n        [\'Upload success\',`${checks.upload_success_percent??0}%`],\n        [\'Open incidents\',checks.open_incidents??0]\n      ].map(([label,value])=>`<article class="site-summary-card"><span class="site-summary-label">${p6eEsc(label)}</span><strong class="site-summary-value">${p6eEsc(value)}</strong></article>`).join(\'\');\n      const drillsResponse=await fetch(\'/api/operations/drills\'), drillsData=await drillsResponse.json();\n      document.getElementById(\'phase6e-drills\').innerHTML=(drillsData.drills||[]).map(item=>`<article class="feature-card"><h3>${p6eEsc(item.scenario)}</h3><p>${p6eEsc(item.result)} · ${p6eEsc(item.recovery_minutes)} minutes · ${p6eEsc(item.owner)}</p><small>${p6eEsc(item.created_at)}</small></article>`).join(\'\')||\'<div class="empty">No incident drills recorded.</div>\';\n    }\n    document.getElementById(\'refresh-phase6e\').onclick=phase6eLoad;\n    document.getElementById(\'phase6e-release-form\').onsubmit=async event=>{\n      event.preventDefault();\n      const payload={release_id:document.getElementById(\'phase6e-release-id\').value,version:document.getElementById(\'phase6e-version\').value,environment:document.getElementById(\'phase6e-environment\').value,notes:document.getElementById(\'phase6e-notes\').value};\n      const response=await fetch(\'/api/operations/deployments/check\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(payload)}),data=await response.json();\n      document.getElementById(\'phase6e-release-result\').textContent=response.ok?`Status: ${data.status}. Blockers: ${(data.blockers||[]).join(\' \')||\'None\'}`:(data.detail||\'Check failed.\');\n    };\n    document.getElementById(\'phase6e-drill-form\').onsubmit=async event=>{\n      event.preventDefault();\n      const payload={scenario:document.getElementById(\'phase6e-scenario\').value,owner:document.getElementById(\'phase6e-owner\').value,result:document.getElementById(\'phase6e-result\').value,recovery_minutes:Number(document.getElementById(\'phase6e-recovery\').value||0),notes:document.getElementById(\'phase6e-drill-notes\').value};\n      const response=await fetch(\'/api/operations/drills\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(payload)}),data=await response.json();\n      showToast(data.message||data.detail||\'Drill saved.\'); if(response.ok){event.currentTarget.reset();phase6eLoad();}\n    };\n    phase6eLoad();\n    </script>\n    """\n    return page_shell("Stability operations", "settings", content, scripts)\n'
PHASE6F_SOURCE = '\n# ============================================================================\n# Phase 6F — Controlled Production Validation and Customer Pilot\n# Explicit approvals, bounded pilot cohorts, validation windows, and rollback\n# checkpoints. This phase does not deploy, activate cloud services, or contact\n# external providers.\n# ============================================================================\n\nPHASE6F_MARKER = "Phase 6F — Controlled Production Validation and Customer Pilot"\nPHASE6F_PILOTS_FILE = RECORDINGS_FOLDER / "phase6f_pilots.json"\nPHASE6F_APPROVALS_FILE = RECORDINGS_FOLDER / "phase6f_approvals.json"\nPHASE6F_VALIDATIONS_FILE = RECORDINGS_FOLDER / "phase6f_validations.json"\nPHASE6F_EVENTS_FILE = RECORDINGS_FOLDER / "phase6f_pilot_events.json"\n\nPHASE6F_MAX_PILOT_CUSTOMERS = int(os.environ.get("PHASE6F_MAX_PILOT_CUSTOMERS", "10"))\nPHASE6F_DEFAULT_WINDOW_HOURS = int(os.environ.get("PHASE6F_DEFAULT_WINDOW_HOURS", "72"))\n\nPHASE6F_REQUIRED_CHECKS = (\n    "customer_consent",\n    "support_contact_confirmed",\n    "rollback_plan_confirmed",\n    "backup_verified",\n    "release_readiness_passed",\n    "monitoring_owner_assigned",\n)\n\n\nclass Phase6FPilotCreateModel(BaseModel):\n    name: str = Field(min_length=3, max_length=160)\n    owner: str = Field(min_length=2, max_length=120)\n    customer_ids: list[str] = Field(default_factory=list, max_length=50)\n    window_hours: int = Field(default=PHASE6F_DEFAULT_WINDOW_HOURS, ge=1, le=720)\n    success_criteria: list[str] = Field(default_factory=list, max_length=30)\n    rollback_trigger: str = Field(min_length=3, max_length=1000)\n    notes: str = Field(default="", max_length=4000)\n\n\nclass Phase6FApprovalModel(BaseModel):\n    decision: str = Field(pattern="^(approved|rejected|revoked)$")\n    approver: str = Field(min_length=2, max_length=120)\n    role: str = Field(min_length=2, max_length=120)\n    notes: str = Field(default="", max_length=2000)\n\n\nclass Phase6FValidationModel(BaseModel):\n    check_key: str = Field(min_length=2, max_length=120)\n    passed: bool\n    evidence: str = Field(default="", max_length=3000)\n\n\nclass Phase6FPilotStatusModel(BaseModel):\n    status: str = Field(pattern="^(draft|ready|active|paused|completed|rolled_back|cancelled)$")\n    reason: str = Field(default="", max_length=2000)\n\n\ndef _phase6f_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef _phase6f_save(path: Path, value) -> None:\n    save_json_file(path, value)\n\n\ndef phase6f_pilot_by_id(pilot_id: str) -> dict | None:\n    return next(\n        (item for item in _phase6f_load(PHASE6F_PILOTS_FILE, []) if item.get("id") == pilot_id),\n        None,\n    )\n\n\ndef phase6f_append_event(pilot_id: str, event: str, actor: str, details: str = "") -> dict:\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "pilot_id": pilot_id,\n        "event": event,\n        "actor": actor,\n        "details": details[:2000],\n        "created_at": datetime.now().isoformat(),\n    }\n    events = _phase6f_load(PHASE6F_EVENTS_FILE, [])\n    events.append(item)\n    _phase6f_save(PHASE6F_EVENTS_FILE, events[-5000:])\n    structured_log(\n        "phase6f.pilot_event",\n        pilot_id=pilot_id,\n        event=event,\n        actor=actor,\n    )\n    return item\n\n\ndef phase6f_pilot_readiness(pilot: dict) -> dict:\n    validations = [\n        item for item in _phase6f_load(PHASE6F_VALIDATIONS_FILE, [])\n        if item.get("pilot_id") == pilot.get("id")\n    ]\n    latest = {}\n    for item in validations:\n        latest[item.get("check_key")] = item\n\n    approvals = [\n        item for item in _phase6f_load(PHASE6F_APPROVALS_FILE, [])\n        if item.get("pilot_id") == pilot.get("id")\n    ]\n    active_approvals = {}\n    for item in approvals:\n        key = (item.get("approver", "").lower(), item.get("role", "").lower())\n        if item.get("decision") == "approved":\n            active_approvals[key] = item\n        elif item.get("decision") in {"rejected", "revoked"}:\n            active_approvals.pop(key, None)\n\n    checks = {\n        key: bool(latest.get(key, {}).get("passed"))\n        for key in PHASE6F_REQUIRED_CHECKS\n    }\n    customer_count = len(pilot.get("customer_ids") or [])\n    bounded_cohort = 1 <= customer_count <= PHASE6F_MAX_PILOT_CUSTOMERS\n    two_person_approval = len(active_approvals) >= 2\n    release_snapshot = phase6e_operational_snapshot() if "phase6e_operational_snapshot" in globals() else {}\n    operationally_healthy = bool(release_snapshot.get("healthy", False))\n\n    blockers = []\n    if not bounded_cohort:\n        blockers.append(\n            f"Pilot must contain between 1 and {PHASE6F_MAX_PILOT_CUSTOMERS} customers."\n        )\n    for key, passed in checks.items():\n        if not passed:\n            blockers.append(f"Required validation is incomplete: {key}.")\n    if not two_person_approval:\n        blockers.append("Two distinct active approvals are required.")\n    if not operationally_healthy:\n        blockers.append("Phase 6E operational snapshot is not healthy.")\n\n    return {\n        "pilot_id": pilot.get("id"),\n        "ready": not blockers,\n        "customer_count": customer_count,\n        "max_customer_count": PHASE6F_MAX_PILOT_CUSTOMERS,\n        "bounded_cohort": bounded_cohort,\n        "required_checks": checks,\n        "active_approval_count": len(active_approvals),\n        "two_person_approval": two_person_approval,\n        "operationally_healthy": operationally_healthy,\n        "blockers": blockers,\n        "safe_action": (\n            "Pilot may be marked ready. Activation still requires a separate explicit status change."\n            if not blockers\n            else "Resolve blockers before changing the pilot to ready or active."\n        ),\n    }\n\n\n@app.get("/api/pilots")\ndef phase6f_list_pilots(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    pilots = _phase6f_load(PHASE6F_PILOTS_FILE, [])\n    enriched = []\n    for pilot in reversed(pilots[-250:]):\n        item = dict(pilot)\n        item["readiness"] = phase6f_pilot_readiness(pilot)\n        enriched.append(item)\n    return {"pilots": enriched}\n\n\n@app.post("/api/pilots")\ndef phase6f_create_pilot(payload: Phase6FPilotCreateModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    customer_ids = list(dict.fromkeys(\n        item.strip() for item in payload.customer_ids if item.strip()\n    ))\n    if len(customer_ids) > PHASE6F_MAX_PILOT_CUSTOMERS:\n        raise HTTPException(\n            status_code=400,\n            detail=f"Pilot cohorts are limited to {PHASE6F_MAX_PILOT_CUSTOMERS} customers.",\n        )\n\n    now = datetime.now()\n    pilot = {\n        "id": uuid.uuid4().hex[:16],\n        "name": payload.name.strip(),\n        "owner": payload.owner.strip(),\n        "customer_ids": customer_ids,\n        "window_hours": payload.window_hours,\n        "success_criteria": [\n            item.strip() for item in payload.success_criteria if item.strip()\n        ],\n        "rollback_trigger": payload.rollback_trigger.strip(),\n        "notes": payload.notes.strip(),\n        "status": "draft",\n        "created_at": now.isoformat(),\n        "updated_at": now.isoformat(),\n        "created_by": user.get("id", "unknown"),\n        "activated_at": None,\n        "completed_at": None,\n        "rolled_back_at": None,\n    }\n    pilots = _phase6f_load(PHASE6F_PILOTS_FILE, [])\n    pilots.append(pilot)\n    _phase6f_save(PHASE6F_PILOTS_FILE, pilots[-1000:])\n    phase6f_append_event(\n        pilot["id"], "pilot_created", user.get("id", "unknown"),\n        f"Cohort size: {len(customer_ids)}"\n    )\n    return {\n        "status": "complete",\n        "message": "Controlled pilot created in draft status.",\n        "pilot": pilot,\n        "readiness": phase6f_pilot_readiness(pilot),\n    }\n\n\n@app.get("/api/pilots/{pilot_id}")\ndef phase6f_get_pilot(pilot_id: str, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    pilot = phase6f_pilot_by_id(pilot_id)\n    if not pilot:\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    approvals = [\n        item for item in _phase6f_load(PHASE6F_APPROVALS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    validations = [\n        item for item in _phase6f_load(PHASE6F_VALIDATIONS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    events = [\n        item for item in _phase6f_load(PHASE6F_EVENTS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    return {\n        "pilot": pilot,\n        "readiness": phase6f_pilot_readiness(pilot),\n        "approvals": approvals,\n        "validations": validations,\n        "events": events[-500:],\n    }\n\n\n@app.post("/api/pilots/{pilot_id}/approvals")\ndef phase6f_record_approval(\n    pilot_id: str, payload: Phase6FApprovalModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    pilot = phase6f_pilot_by_id(pilot_id)\n    if not pilot:\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    approval = {\n        "id": uuid.uuid4().hex[:16],\n        "pilot_id": pilot_id,\n        "decision": payload.decision,\n        "approver": payload.approver.strip(),\n        "role": payload.role.strip(),\n        "notes": payload.notes.strip(),\n        "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n    }\n    approvals = _phase6f_load(PHASE6F_APPROVALS_FILE, [])\n    approvals.append(approval)\n    _phase6f_save(PHASE6F_APPROVALS_FILE, approvals[-5000:])\n    phase6f_append_event(\n        pilot_id, f"approval_{payload.decision}", user.get("id", "unknown"),\n        f"{approval[\'approver\']} ({approval[\'role\']})"\n    )\n    return {\n        "status": "complete",\n        "message": f"Pilot approval recorded as {payload.decision}.",\n        "approval": approval,\n        "readiness": phase6f_pilot_readiness(pilot),\n    }\n\n\n@app.post("/api/pilots/{pilot_id}/validations")\ndef phase6f_record_validation(\n    pilot_id: str, payload: Phase6FValidationModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    pilot = phase6f_pilot_by_id(pilot_id)\n    if not pilot:\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    allowed = set(PHASE6F_REQUIRED_CHECKS) | {\n        "camera_health_verified",\n        "recording_verified",\n        "mobile_access_verified",\n        "customer_training_complete",\n        "support_escalation_tested",\n    }\n    if payload.check_key not in allowed:\n        raise HTTPException(status_code=400, detail="Unknown pilot validation check.")\n    validation = {\n        "id": uuid.uuid4().hex[:16],\n        "pilot_id": pilot_id,\n        "check_key": payload.check_key,\n        "passed": payload.passed,\n        "evidence": payload.evidence.strip(),\n        "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n    }\n    validations = _phase6f_load(PHASE6F_VALIDATIONS_FILE, [])\n    validations.append(validation)\n    _phase6f_save(PHASE6F_VALIDATIONS_FILE, validations[-10000:])\n    phase6f_append_event(\n        pilot_id,\n        "validation_passed" if payload.passed else "validation_failed",\n        user.get("id", "unknown"),\n        payload.check_key,\n    )\n    return {\n        "status": "complete",\n        "message": "Pilot validation recorded.",\n        "validation": validation,\n        "readiness": phase6f_pilot_readiness(pilot),\n    }\n\n\n@app.put("/api/pilots/{pilot_id}/status")\ndef phase6f_change_pilot_status(\n    pilot_id: str, payload: Phase6FPilotStatusModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    pilots = _phase6f_load(PHASE6F_PILOTS_FILE, [])\n    pilot = next((item for item in pilots if item.get("id") == pilot_id), None)\n    if not pilot:\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n\n    current = pilot.get("status", "draft")\n    target = payload.status\n    allowed = {\n        "draft": {"ready", "cancelled"},\n        "ready": {"active", "draft", "cancelled"},\n        "active": {"paused", "completed", "rolled_back"},\n        "paused": {"active", "rolled_back", "cancelled"},\n        "completed": set(),\n        "rolled_back": set(),\n        "cancelled": set(),\n    }\n    if target not in allowed.get(current, set()):\n        raise HTTPException(\n            status_code=400,\n            detail=f"Pilot cannot move from {current} to {target}.",\n        )\n\n    readiness = phase6f_pilot_readiness(pilot)\n    if target in {"ready", "active"} and not readiness["ready"]:\n        raise HTTPException(\n            status_code=409,\n            detail="Pilot readiness blockers must be cleared before this status change.",\n        )\n\n    now = datetime.now().isoformat()\n    pilot["status"] = target\n    pilot["updated_at"] = now\n    pilot["status_reason"] = payload.reason.strip()\n    if target == "active":\n        pilot["activated_at"] = now\n    elif target == "completed":\n        pilot["completed_at"] = now\n    elif target == "rolled_back":\n        pilot["rolled_back_at"] = now\n\n    _phase6f_save(PHASE6F_PILOTS_FILE, pilots)\n    phase6f_append_event(\n        pilot_id, f"status_{target}", user.get("id", "unknown"), payload.reason\n    )\n    return {\n        "status": "complete",\n        "message": f"Pilot status changed to {target}.",\n        "pilot": pilot,\n        "readiness": phase6f_pilot_readiness(pilot),\n        "external_action_performed": False,\n    }\n\n\n@app.get("/pilots", response_class=HTMLResponse)\ndef phase6f_pilots_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    content = """\n    <header class="topbar">\n      <div><p class="eyebrow">Phase 6F</p><h1>Controlled customer pilots</h1></div>\n      <span class="pill">Approval-gated</span>\n    </header>\n    <section class="panel">\n      <div class="panel-head"><div><h2>Create bounded pilot</h2><div class="health-detail">Creates a local pilot record only. It does not deploy, activate cameras, or contact a provider.</div></div></div>\n      <form id="phase6f-create" class="settings-grid">\n        <label>Pilot name<input id="p6f-name" required placeholder="Houston assisted-living pilot"></label>\n        <label>Owner<input id="p6f-owner" required placeholder="Pilot operations lead"></label>\n        <label>Customer IDs<textarea id="p6f-customers" rows="4" placeholder="One customer ID per line"></textarea></label>\n        <label>Window hours<input id="p6f-window" type="number" min="1" max="720" value="72"></label>\n        <label>Success criteria<textarea id="p6f-success" rows="4" placeholder="One criterion per line"></textarea></label>\n        <label>Rollback trigger<textarea id="p6f-rollback" rows="4" required placeholder="Example: recording success below 99% for 15 minutes"></textarea></label>\n        <label>Notes<textarea id="p6f-notes" rows="3"></textarea></label>\n        <div><button class="action-button" type="submit">Create draft pilot</button></div>\n      </form>\n    </section>\n    <section class="panel">\n      <div class="panel-head"><div><h2>Pilot register</h2><div class="health-detail">Readiness requires all mandatory checks, two active approvals, and a healthy Phase 6E snapshot.</div></div><button class="secondary-button" id="p6f-refresh">Refresh</button></div>\n      <div id="p6f-list"></div>\n    </section>\n    """\n    scripts = """\n    <script>\n    const p6fEsc=value=>String(value??\'\').replace(/[&<>"\']/g,ch=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[ch]));\n    const p6fLines=id=>document.getElementById(id).value.split(/\\\\r?\\\\n/).map(x=>x.trim()).filter(Boolean);\n    async function p6fLoad(){\n      const response=await fetch(\'/api/pilots\'),data=await response.json();\n      if(!response.ok){showToast(data.detail||\'Could not load pilots.\');return;}\n      document.getElementById(\'p6f-list\').innerHTML=(data.pilots||[]).map(item=>{\n        const r=item.readiness||{};\n        return `<article class="feature-card">\n          <div class="panel-head"><div><h3>${p6fEsc(item.name)}</h3><p>${p6fEsc(item.owner)} · ${p6fEsc(item.customer_ids?.length||0)} customers · ${p6fEsc(item.window_hours)} hours</p></div><span class="pill">${p6fEsc(item.status)}</span></div>\n          <p><b>Readiness:</b> ${r.ready?\'Ready\':\'Blocked\'} · approvals ${p6fEsc(r.active_approval_count||0)}/2</p>\n          <p class="health-detail">${p6fEsc((r.blockers||[]).join(\' \')||\'All readiness gates are satisfied.\')}</p>\n          <a class="secondary-button" href="/api/pilots/${encodeURIComponent(item.id)}">View pilot JSON</a>\n        </article>`;\n      }).join(\'\')||\'<div class="empty">No pilot records exist.</div>\';\n    }\n    document.getElementById(\'p6f-refresh\').onclick=p6fLoad;\n    document.getElementById(\'phase6f-create\').onsubmit=async event=>{\n      event.preventDefault();\n      const payload={\n        name:document.getElementById(\'p6f-name\').value,\n        owner:document.getElementById(\'p6f-owner\').value,\n        customer_ids:p6fLines(\'p6f-customers\'),\n        window_hours:Number(document.getElementById(\'p6f-window\').value||72),\n        success_criteria:p6fLines(\'p6f-success\'),\n        rollback_trigger:document.getElementById(\'p6f-rollback\').value,\n        notes:document.getElementById(\'p6f-notes\').value\n      };\n      const response=await fetch(\'/api/pilots\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(payload)}),data=await response.json();\n      showToast(data.message||data.detail||\'Pilot request complete.\');\n      if(response.ok){event.currentTarget.reset();document.getElementById(\'p6f-window\').value=\'72\';p6fLoad();}\n    };\n    p6fLoad();\n    </script>\n    """\n    return page_shell("Controlled pilots", "settings", content, scripts)\n'
PHASE6G_SOURCE = '\n# ============================================================================\n# Phase 6G — Pilot Telemetry, Outcome Review, and Go/No-Go Decision\n# Local-only review and decision controls. No automatic rollout is performed.\n# ============================================================================\n\nPHASE6G_MARKER = "Phase 6G — Pilot Telemetry, Outcome Review, and Go/No-Go Decision"\nPHASE6G_TELEMETRY_FILE = RECORDINGS_FOLDER / "phase6g_pilot_telemetry.json"\nPHASE6G_FEEDBACK_FILE = RECORDINGS_FOLDER / "phase6g_customer_feedback.json"\nPHASE6G_DECISIONS_FILE = RECORDINGS_FOLDER / "phase6g_launch_decisions.json"\nPHASE6G_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6g_outcome_reviews.json"\n\nPHASE6G_MIN_SAMPLE_POINTS = int(os.environ.get("PHASE6G_MIN_SAMPLE_POINTS", "3"))\nPHASE6G_MAX_ERROR_RATE = float(os.environ.get("PHASE6G_MAX_ERROR_RATE", "2.0"))\nPHASE6G_MIN_SUCCESS_RATE = float(os.environ.get("PHASE6G_MIN_SUCCESS_RATE", "98.0"))\nPHASE6G_MIN_CUSTOMER_SCORE = float(os.environ.get("PHASE6G_MIN_CUSTOMER_SCORE", "4.0"))\n\n\nclass Phase6GTelemetryModel(BaseModel):\n    metric: str = Field(min_length=2, max_length=120)\n    value: float\n    unit: str = Field(default="", max_length=40)\n    source: str = Field(default="manual", max_length=120)\n    notes: str = Field(default="", max_length=2000)\n\n\nclass Phase6GFeedbackModel(BaseModel):\n    customer_id: str = Field(min_length=1, max_length=160)\n    score: float = Field(ge=1, le=5)\n    category: str = Field(default="general", max_length=120)\n    comments: str = Field(default="", max_length=3000)\n\n\nclass Phase6GDecisionModel(BaseModel):\n    decision: str = Field(pattern="^(go|no_go|extend_pilot)$")\n    approver: str = Field(min_length=2, max_length=120)\n    role: str = Field(min_length=2, max_length=120)\n    rationale: str = Field(min_length=5, max_length=4000)\n    acknowledged_risks: list[str] = Field(default_factory=list, max_length=50)\n\n\ndef _phase6g_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef _phase6g_save(path: Path, value) -> None:\n    save_json_file(path, value)\n\n\ndef phase6g_pilot_metrics(pilot_id: str) -> dict:\n    telemetry = [\n        item for item in _phase6g_load(PHASE6G_TELEMETRY_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    feedback = [\n        item for item in _phase6g_load(PHASE6G_FEEDBACK_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    grouped = {}\n    for item in telemetry:\n        grouped.setdefault(item.get("metric"), []).append(float(item.get("value", 0)))\n    averages = {\n        key: round(sum(values) / len(values), 3)\n        for key, values in grouped.items() if values\n    }\n    customer_score = (\n        round(sum(float(item.get("score", 0)) for item in feedback) / len(feedback), 3)\n        if feedback else 0.0\n    )\n    return {\n        "pilot_id": pilot_id,\n        "sample_count": len(telemetry),\n        "feedback_count": len(feedback),\n        "averages": averages,\n        "success_rate": averages.get("success_rate", 0.0),\n        "error_rate": averages.get("error_rate", 100.0),\n        "availability": averages.get("availability", 0.0),\n        "customer_score": customer_score,\n    }\n\n\ndef phase6g_outcome_review(pilot_id: str) -> dict:\n    pilot = phase6f_pilot_by_id(pilot_id)\n    if not pilot:\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    metrics = phase6g_pilot_metrics(pilot_id)\n    readiness = phase6f_pilot_readiness(pilot)\n    events = [\n        item for item in _phase6f_load(PHASE6F_EVENTS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    rolled_back = pilot.get("status") == "rolled_back" or any(\n        item.get("event") == "status_rolled_back" for item in events\n    )\n    blockers = []\n    if metrics["sample_count"] < PHASE6G_MIN_SAMPLE_POINTS:\n        blockers.append(f"At least {PHASE6G_MIN_SAMPLE_POINTS} telemetry samples are required.")\n    if metrics["success_rate"] < PHASE6G_MIN_SUCCESS_RATE:\n        blockers.append("Pilot success rate is below threshold.")\n    if metrics["error_rate"] > PHASE6G_MAX_ERROR_RATE:\n        blockers.append("Pilot error rate exceeds threshold.")\n    if metrics["feedback_count"] and metrics["customer_score"] < PHASE6G_MIN_CUSTOMER_SCORE:\n        blockers.append("Customer feedback score is below threshold.")\n    if rolled_back:\n        blockers.append("Pilot entered rollback status.")\n    if pilot.get("status") not in {"active", "paused", "completed"}:\n        blockers.append("Pilot must be active, paused, or completed.")\n    if not readiness.get("operationally_healthy", False):\n        blockers.append("Phase 6E operational health is not healthy.")\n\n    recommendation = "go"\n    if rolled_back or metrics["error_rate"] > PHASE6G_MAX_ERROR_RATE:\n        recommendation = "no_go"\n    elif blockers:\n        recommendation = "extend_pilot"\n\n    review = {\n        "id": uuid.uuid4().hex[:16],\n        "pilot_id": pilot_id,\n        "created_at": datetime.now().isoformat(),\n        "pilot_status": pilot.get("status"),\n        "metrics": metrics,\n        "blockers": blockers,\n        "recommendation": recommendation,\n        "automatic_launch_performed": False,\n    }\n    reviews = _phase6g_load(PHASE6G_REVIEWS_FILE, [])\n    reviews.append(review)\n    _phase6g_save(PHASE6G_REVIEWS_FILE, reviews[-2000:])\n    structured_log(\n        "phase6g.outcome_review",\n        pilot_id=pilot_id,\n        recommendation=recommendation,\n        blocker_count=len(blockers),\n    )\n    return review\n\n\n@app.post("/api/pilots/{pilot_id}/telemetry")\ndef phase6g_record_telemetry(pilot_id: str, payload: Phase6GTelemetryModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6f_pilot_by_id(pilot_id):\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16], "pilot_id": pilot_id,\n        "metric": payload.metric.strip(), "value": payload.value,\n        "unit": payload.unit.strip(), "source": payload.source.strip(),\n        "notes": payload.notes.strip(), "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n    }\n    records = _phase6g_load(PHASE6G_TELEMETRY_FILE, [])\n    records.append(item)\n    _phase6g_save(PHASE6G_TELEMETRY_FILE, records[-20000:])\n    phase6f_append_event(pilot_id, "telemetry_recorded", user.get("id", "unknown"), payload.metric)\n    return {"status": "complete", "telemetry": item, "metrics": phase6g_pilot_metrics(pilot_id)}\n\n\n@app.post("/api/pilots/{pilot_id}/feedback")\ndef phase6g_record_feedback(pilot_id: str, payload: Phase6GFeedbackModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6f_pilot_by_id(pilot_id):\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16], "pilot_id": pilot_id,\n        "customer_id": payload.customer_id.strip(), "score": payload.score,\n        "category": payload.category.strip(), "comments": payload.comments.strip(),\n        "recorded_by": user.get("id", "unknown"), "created_at": datetime.now().isoformat(),\n    }\n    records = _phase6g_load(PHASE6G_FEEDBACK_FILE, [])\n    records.append(item)\n    _phase6g_save(PHASE6G_FEEDBACK_FILE, records[-10000:])\n    phase6f_append_event(pilot_id, "customer_feedback_recorded", user.get("id", "unknown"), f"score={payload.score}")\n    return {"status": "complete", "feedback": item, "metrics": phase6g_pilot_metrics(pilot_id)}\n\n\n@app.get("/api/pilots/{pilot_id}/outcome-review")\ndef phase6g_review_api(pilot_id: str, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    return phase6g_outcome_review(pilot_id)\n\n\n@app.post("/api/pilots/{pilot_id}/decisions")\ndef phase6g_decision_api(pilot_id: str, payload: Phase6GDecisionModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6f_pilot_by_id(pilot_id):\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n    review = phase6g_outcome_review(pilot_id)\n    if payload.decision == "go" and review["recommendation"] != "go":\n        raise HTTPException(status_code=409, detail="Go decision is blocked by the current outcome review.")\n    item = {\n        "id": uuid.uuid4().hex[:16], "pilot_id": pilot_id,\n        "decision": payload.decision, "approver": payload.approver.strip(),\n        "role": payload.role.strip(), "rationale": payload.rationale.strip(),\n        "acknowledged_risks": [x.strip() for x in payload.acknowledged_risks if x.strip()],\n        "review_id": review["id"], "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n        "external_action_performed": False, "automatic_rollout_performed": False,\n    }\n    records = _phase6g_load(PHASE6G_DECISIONS_FILE, [])\n    records.append(item)\n    _phase6g_save(PHASE6G_DECISIONS_FILE, records[-5000:])\n    phase6f_append_event(pilot_id, f"launch_decision_{payload.decision}", user.get("id", "unknown"), payload.rationale)\n    return {"status": "complete", "decision": item, "review": review}\n\n\n@app.get("/pilot-review", response_class=HTMLResponse)\ndef phase6g_review_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    content = """\n    <header class="topbar"><div><p class="eyebrow">Phase 6G</p><h1>Pilot outcome review</h1></div><span class="pill">No automatic rollout</span></header>\n    <section class="panel">\n      <label>Pilot ID<input id="p6g-id" placeholder="Pilot ID"></label>\n      <div style="margin-top:12px"><button class="action-button" id="p6g-review">Run outcome review</button></div>\n      <pre id="p6g-output" style="white-space:pre-wrap;margin-top:16px"></pre>\n    </section>\n    """\n    scripts = """\n    <script>\n    document.getElementById(\'p6g-review\').onclick=async()=>{\n      const id=document.getElementById(\'p6g-id\').value.trim();\n      const response=await fetch(`/api/pilots/${encodeURIComponent(id)}/outcome-review`);\n      const data=await response.json();\n      document.getElementById(\'p6g-output\').textContent=JSON.stringify(data,null,2);\n      if(!response.ok) showToast(data.detail||\'Review failed.\');\n    };\n    </script>\n    """\n    return page_shell("Pilot outcome review", "settings", content, scripts)\n'
PHASE6H_SOURCE = '\n# ============================================================================\n# Phase 6H — Controlled Rollout Governance and Launch Readiness\n# Approval-gated rollout planning, staged cohorts, launch windows, and formal\n# rollback checkpoints. No automatic rollout or provider activation occurs.\n# ============================================================================\n\nPHASE6H_MARKER = "Phase 6H — Controlled Rollout Governance and Launch Readiness"\nPHASE6H_PLANS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_plans.json"\nPHASE6H_APPROVALS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_approvals.json"\nPHASE6H_CHECKPOINTS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_checkpoints.json"\nPHASE6H_EVENTS_FILE = RECORDINGS_FOLDER / "phase6h_rollout_events.json"\n\nPHASE6H_MAX_STAGE_PERCENT = float(os.environ.get("PHASE6H_MAX_STAGE_PERCENT", "25"))\nPHASE6H_REQUIRED_APPROVALS = int(os.environ.get("PHASE6H_REQUIRED_APPROVALS", "2"))\nPHASE6H_MAX_ACTIVE_STAGE = int(os.environ.get("PHASE6H_MAX_ACTIVE_STAGE", "1"))\n\n\nclass Phase6HRolloutPlanModel(BaseModel):\n    name: str = Field(min_length=3, max_length=160)\n    owner: str = Field(min_length=2, max_length=120)\n    pilot_id: str = Field(min_length=2, max_length=120)\n    total_customers: int = Field(ge=1, le=1000000)\n    stages: list[int] = Field(min_length=1, max_length=20)\n    rollback_trigger: str = Field(min_length=5, max_length=3000)\n    maintenance_window: str = Field(min_length=3, max_length=300)\n    notes: str = Field(default="", max_length=4000)\n\n\nclass Phase6HRolloutApprovalModel(BaseModel):\n    decision: str = Field(pattern="^(approved|rejected|revoked)$")\n    approver: str = Field(min_length=2, max_length=120)\n    role: str = Field(min_length=2, max_length=120)\n    notes: str = Field(default="", max_length=2000)\n\n\nclass Phase6HCheckpointModel(BaseModel):\n    stage_number: int = Field(ge=1, le=100)\n    status: str = Field(pattern="^(pending|ready|active|paused|completed|rolled_back|cancelled)$")\n    success_rate: float = Field(default=0, ge=0, le=100)\n    error_rate: float = Field(default=0, ge=0, le=100)\n    notes: str = Field(default="", max_length=3000)\n\n\ndef _phase6h_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef _phase6h_save(path: Path, value) -> None:\n    save_json_file(path, value)\n\n\ndef phase6h_plan_by_id(plan_id: str) -> dict | None:\n    return next(\n        (item for item in _phase6h_load(PHASE6H_PLANS_FILE, []) if item.get("id") == plan_id),\n        None,\n    )\n\n\ndef phase6h_append_event(plan_id: str, event: str, actor: str, details: str = "") -> dict:\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "event": event,\n        "actor": actor,\n        "details": details[:2000],\n        "created_at": datetime.now().isoformat(),\n    }\n    events = _phase6h_load(PHASE6H_EVENTS_FILE, [])\n    events.append(item)\n    _phase6h_save(PHASE6H_EVENTS_FILE, events[-10000:])\n    structured_log("phase6h.rollout_event", plan_id=plan_id, event=event, actor=actor)\n    return item\n\n\ndef phase6h_plan_readiness(plan: dict) -> dict:\n    pilot_id = plan.get("pilot_id")\n    pilot = phase6f_pilot_by_id(pilot_id)\n    reviews = [\n        item for item in _phase6g_load(PHASE6G_REVIEWS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    decisions = [\n        item for item in _phase6g_load(PHASE6G_DECISIONS_FILE, [])\n        if item.get("pilot_id") == pilot_id\n    ]\n    latest_review = reviews[-1] if reviews else None\n    latest_decision = decisions[-1] if decisions else None\n\n    approvals = [\n        item for item in _phase6h_load(PHASE6H_APPROVALS_FILE, [])\n        if item.get("plan_id") == plan.get("id")\n    ]\n    active_approvals = {}\n    for item in approvals:\n        key = (item.get("approver", "").lower(), item.get("role", "").lower())\n        if item.get("decision") == "approved":\n            active_approvals[key] = item\n        elif item.get("decision") in {"rejected", "revoked"}:\n            active_approvals.pop(key, None)\n\n    stages = plan.get("stages") or []\n    stage_sum = sum(stages)\n    max_stage = max(stages) if stages else 0\n    blockers = []\n\n    if not pilot:\n        blockers.append("Referenced pilot does not exist.")\n    if not latest_review or latest_review.get("recommendation") != "go":\n        blockers.append("Latest Phase 6G outcome review is not GO.")\n    if not latest_decision or latest_decision.get("decision") != "go":\n        blockers.append("Formal Phase 6G GO decision is missing.")\n    if len(active_approvals) < PHASE6H_REQUIRED_APPROVALS:\n        blockers.append(f"{PHASE6H_REQUIRED_APPROVALS} rollout approvals are required.")\n    if stage_sum != 100:\n        blockers.append("Rollout stage percentages must total 100.")\n    if max_stage > PHASE6H_MAX_STAGE_PERCENT:\n        blockers.append(\n            f"No rollout stage may exceed {PHASE6H_MAX_STAGE_PERCENT:g}%."\n        )\n    if not plan.get("rollback_trigger"):\n        blockers.append("Rollback trigger is required.")\n    if not plan.get("maintenance_window"):\n        blockers.append("Maintenance window is required.")\n\n    return {\n        "plan_id": plan.get("id"),\n        "ready": not blockers,\n        "pilot_id": pilot_id,\n        "active_approval_count": len(active_approvals),\n        "required_approval_count": PHASE6H_REQUIRED_APPROVALS,\n        "stage_total_percent": stage_sum,\n        "largest_stage_percent": max_stage,\n        "latest_review_recommendation": latest_review.get("recommendation") if latest_review else None,\n        "latest_launch_decision": latest_decision.get("decision") if latest_decision else None,\n        "blockers": blockers,\n        "automatic_rollout_performed": False,\n    }\n\n\n@app.get("/api/rollouts")\ndef phase6h_list_rollouts(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    plans = _phase6h_load(PHASE6H_PLANS_FILE, [])\n    return {\n        "rollouts": [\n            {**item, "readiness": phase6h_plan_readiness(item)}\n            for item in reversed(plans[-500:])\n        ]\n    }\n\n\n@app.post("/api/rollouts")\ndef phase6h_create_rollout(payload: Phase6HRolloutPlanModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if sum(payload.stages) != 100:\n        raise HTTPException(status_code=400, detail="Rollout stages must total 100 percent.")\n    if max(payload.stages) > PHASE6H_MAX_STAGE_PERCENT:\n        raise HTTPException(\n            status_code=400,\n            detail=f"Each rollout stage is limited to {PHASE6H_MAX_STAGE_PERCENT:g} percent.",\n        )\n    if not phase6f_pilot_by_id(payload.pilot_id):\n        raise HTTPException(status_code=404, detail="Pilot not found.")\n\n    now = datetime.now().isoformat()\n    plan = {\n        "id": uuid.uuid4().hex[:16],\n        "name": payload.name.strip(),\n        "owner": payload.owner.strip(),\n        "pilot_id": payload.pilot_id.strip(),\n        "total_customers": payload.total_customers,\n        "stages": payload.stages,\n        "rollback_trigger": payload.rollback_trigger.strip(),\n        "maintenance_window": payload.maintenance_window.strip(),\n        "notes": payload.notes.strip(),\n        "status": "draft",\n        "current_stage": 0,\n        "created_at": now,\n        "updated_at": now,\n        "created_by": user.get("id", "unknown"),\n    }\n    plans = _phase6h_load(PHASE6H_PLANS_FILE, [])\n    plans.append(plan)\n    _phase6h_save(PHASE6H_PLANS_FILE, plans[-2000:])\n    phase6h_append_event(plan["id"], "rollout_plan_created", user.get("id", "unknown"))\n    return {\n        "status": "complete",\n        "message": "Rollout plan created in draft status.",\n        "plan": plan,\n        "readiness": phase6h_plan_readiness(plan),\n        "external_action_performed": False,\n    }\n\n\n@app.post("/api/rollouts/{plan_id}/approvals")\ndef phase6h_approval(plan_id: str, payload: Phase6HRolloutApprovalModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    plan = phase6h_plan_by_id(plan_id)\n    if not plan:\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "decision": payload.decision,\n        "approver": payload.approver.strip(),\n        "role": payload.role.strip(),\n        "notes": payload.notes.strip(),\n        "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n    }\n    approvals = _phase6h_load(PHASE6H_APPROVALS_FILE, [])\n    approvals.append(item)\n    _phase6h_save(PHASE6H_APPROVALS_FILE, approvals[-10000:])\n    phase6h_append_event(plan_id, f"approval_{payload.decision}", user.get("id", "unknown"))\n    return {"status": "complete", "approval": item, "readiness": phase6h_plan_readiness(plan)}\n\n\n@app.post("/api/rollouts/{plan_id}/checkpoints")\ndef phase6h_checkpoint(plan_id: str, payload: Phase6HCheckpointModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    plan = phase6h_plan_by_id(plan_id)\n    if not plan:\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n    if payload.stage_number > len(plan.get("stages") or []):\n        raise HTTPException(status_code=400, detail="Stage number exceeds rollout plan.")\n    if payload.status in {"ready", "active"} and not phase6h_plan_readiness(plan)["ready"]:\n        raise HTTPException(status_code=409, detail="Rollout readiness blockers remain.")\n\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "stage_number": payload.stage_number,\n        "stage_percent": plan["stages"][payload.stage_number - 1],\n        "status": payload.status,\n        "success_rate": payload.success_rate,\n        "error_rate": payload.error_rate,\n        "notes": payload.notes.strip(),\n        "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n        "external_action_performed": False,\n    }\n    records = _phase6h_load(PHASE6H_CHECKPOINTS_FILE, [])\n    records.append(item)\n    _phase6h_save(PHASE6H_CHECKPOINTS_FILE, records[-20000:])\n    phase6h_append_event(\n        plan_id, f"checkpoint_{payload.status}", user.get("id", "unknown"),\n        f"stage={payload.stage_number}"\n    )\n    return {\n        "status": "complete",\n        "checkpoint": item,\n        "automatic_rollout_performed": False,\n    }\n\n\n@app.get("/rollouts", response_class=HTMLResponse)\ndef phase6h_rollouts_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    content = """\n    <header class="topbar">\n      <div><p class="eyebrow">Phase 6H</p><h1>Controlled rollout governance</h1></div>\n      <span class="pill">Manual execution only</span>\n    </header>\n    <section class="panel">\n      <div class="panel-head"><div><h2>Rollout register</h2><div class="health-detail">Plans and checkpoints are recorded locally. No customer rollout is executed automatically.</div></div><button class="secondary-button" id="p6h-refresh">Refresh</button></div>\n      <div id="p6h-list"></div>\n    </section>\n    """\n    scripts = """\n    <script>\n    const p6hEsc=value=>String(value??\'\').replace(/[&<>"\']/g,ch=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[ch]));\n    async function p6hLoad(){\n      const response=await fetch(\'/api/rollouts\'),data=await response.json();\n      if(!response.ok){showToast(data.detail||\'Could not load rollouts.\');return;}\n      document.getElementById(\'p6h-list\').innerHTML=(data.rollouts||[]).map(item=>{\n        const r=item.readiness||{};\n        return `<article class="feature-card"><div class="panel-head"><div><h3>${p6hEsc(item.name)}</h3><p>${p6hEsc(item.owner)} · ${p6hEsc(item.total_customers)} customers</p></div><span class="pill">${p6hEsc(item.status)}</span></div><p><b>Readiness:</b> ${r.ready?\'Ready\':\'Blocked\'}</p><p class="health-detail">${p6hEsc((r.blockers||[]).join(\' \')||\'All rollout governance gates are satisfied.\')}</p></article>`;\n      }).join(\'\')||\'<div class="empty">No rollout plans exist.</div>\';\n    }\n    document.getElementById(\'p6h-refresh\').onclick=p6hLoad;\n    p6hLoad();\n    </script>\n    """\n    return page_shell("Controlled rollouts", "settings", content, scripts)\n'
PHASE6I_SOURCE = '\n# ============================================================================\n# Phase 6I — Rollout Observation, Exception Control, and Post-Launch Assurance\n# Local operational records only. No automatic deployment, rollback, customer\n# activation, or external provider action is performed.\n# ============================================================================\n\nPHASE6I_MARKER = "Phase 6I — Rollout Observation, Exception Control, and Post-Launch Assurance"\nPHASE6I_OBSERVATIONS_FILE = RECORDINGS_FOLDER / "phase6i_rollout_observations.json"\nPHASE6I_EXCEPTIONS_FILE = RECORDINGS_FOLDER / "phase6i_rollout_exceptions.json"\nPHASE6I_ASSURANCE_FILE = RECORDINGS_FOLDER / "phase6i_post_launch_assurance.json"\nPHASE6I_SIGNOFFS_FILE = RECORDINGS_FOLDER / "phase6i_assurance_signoffs.json"\n\nPHASE6I_MAX_ERROR_RATE = float(os.environ.get("PHASE6I_MAX_ERROR_RATE", "2.0"))\nPHASE6I_MIN_SUCCESS_RATE = float(os.environ.get("PHASE6I_MIN_SUCCESS_RATE", "98.0"))\nPHASE6I_MIN_AVAILABILITY = float(os.environ.get("PHASE6I_MIN_AVAILABILITY", "99.0"))\nPHASE6I_REQUIRED_SIGNOFFS = int(os.environ.get("PHASE6I_REQUIRED_SIGNOFFS", "2"))\n\n\nclass Phase6IObservationModel(BaseModel):\n    stage_number: int = Field(ge=1, le=100)\n    success_rate: float = Field(ge=0, le=100)\n    error_rate: float = Field(ge=0, le=100)\n    availability: float = Field(ge=0, le=100)\n    customer_count: int = Field(ge=0, le=1000000)\n    notes: str = Field(default="", max_length=3000)\n\n\nclass Phase6IExceptionModel(BaseModel):\n    severity: str = Field(pattern="^(low|medium|high|critical)$")\n    category: str = Field(min_length=2, max_length=120)\n    summary: str = Field(min_length=5, max_length=1000)\n    owner: str = Field(min_length=2, max_length=120)\n    containment: str = Field(default="", max_length=3000)\n\n\nclass Phase6IExceptionStatusModel(BaseModel):\n    status: str = Field(pattern="^(open|contained|resolved|accepted)$")\n    notes: str = Field(default="", max_length=3000)\n\n\nclass Phase6ISignoffModel(BaseModel):\n    decision: str = Field(pattern="^(approved|rejected|revoked)$")\n    approver: str = Field(min_length=2, max_length=120)\n    role: str = Field(min_length=2, max_length=120)\n    notes: str = Field(default="", max_length=3000)\n\n\ndef _phase6i_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef _phase6i_save(path: Path, value) -> None:\n    save_json_file(path, value)\n\n\ndef phase6i_rollout_assurance(plan_id: str) -> dict:\n    plan = phase6h_plan_by_id(plan_id)\n    if not plan:\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n\n    observations = [\n        item for item in _phase6i_load(PHASE6I_OBSERVATIONS_FILE, [])\n        if item.get("plan_id") == plan_id\n    ]\n    exceptions = [\n        item for item in _phase6i_load(PHASE6I_EXCEPTIONS_FILE, [])\n        if item.get("plan_id") == plan_id\n    ]\n    signoffs = [\n        item for item in _phase6i_load(PHASE6I_SIGNOFFS_FILE, [])\n        if item.get("plan_id") == plan_id\n    ]\n\n    active_signoffs = {}\n    for item in signoffs:\n        key = (item.get("approver", "").lower(), item.get("role", "").lower())\n        if item.get("decision") == "approved":\n            active_signoffs[key] = item\n        elif item.get("decision") in {"rejected", "revoked"}:\n            active_signoffs.pop(key, None)\n\n    latest_by_stage = {}\n    for item in observations:\n        latest_by_stage[item.get("stage_number")] = item\n\n    active_exceptions = [\n        item for item in exceptions\n        if item.get("status", "open") not in {"resolved", "accepted"}\n    ]\n    critical_exceptions = [\n        item for item in active_exceptions if item.get("severity") == "critical"\n    ]\n\n    failed_stages = []\n    for stage, item in latest_by_stage.items():\n        if (\n            float(item.get("success_rate", 0)) < PHASE6I_MIN_SUCCESS_RATE\n            or float(item.get("error_rate", 100)) > PHASE6I_MAX_ERROR_RATE\n            or float(item.get("availability", 0)) < PHASE6I_MIN_AVAILABILITY\n        ):\n            failed_stages.append(stage)\n\n    blockers = []\n    if not observations:\n        blockers.append("No rollout observations have been recorded.")\n    if failed_stages:\n        blockers.append(f"Stages outside assurance thresholds: {sorted(failed_stages)}.")\n    if critical_exceptions:\n        blockers.append("Critical rollout exceptions remain unresolved.")\n    if len(active_signoffs) < PHASE6I_REQUIRED_SIGNOFFS:\n        blockers.append(f"{PHASE6I_REQUIRED_SIGNOFFS} assurance signoffs are required.")\n\n    completed_stages = len({\n        item.get("stage_number")\n        for item in observations\n        if item.get("status") == "completed"\n    })\n    expected_stages = len(plan.get("stages") or [])\n    if completed_stages < expected_stages:\n        blockers.append(\n            f"Only {completed_stages} of {expected_stages} rollout stages are marked completed."\n        )\n\n    result = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "checked_at": datetime.now().isoformat(),\n        "assured": not blockers,\n        "observation_count": len(observations),\n        "active_exception_count": len(active_exceptions),\n        "critical_exception_count": len(critical_exceptions),\n        "active_signoff_count": len(active_signoffs),\n        "required_signoff_count": PHASE6I_REQUIRED_SIGNOFFS,\n        "completed_stage_count": completed_stages,\n        "expected_stage_count": expected_stages,\n        "failed_stages": sorted(failed_stages),\n        "blockers": blockers,\n        "automatic_action_performed": False,\n    }\n    records = _phase6i_load(PHASE6I_ASSURANCE_FILE, [])\n    records.append(result)\n    _phase6i_save(PHASE6I_ASSURANCE_FILE, records[-5000:])\n    structured_log(\n        "phase6i.assurance_review",\n        plan_id=plan_id,\n        assured=result["assured"],\n        blocker_count=len(blockers),\n    )\n    return result\n\n\n@app.post("/api/rollouts/{plan_id}/observations")\ndef phase6i_observation(plan_id: str, payload: Phase6IObservationModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    plan = phase6h_plan_by_id(plan_id)\n    if not plan:\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n    if payload.stage_number > len(plan.get("stages") or []):\n        raise HTTPException(status_code=400, detail="Stage number exceeds rollout plan.")\n\n    status = "completed"\n    if (\n        payload.success_rate < PHASE6I_MIN_SUCCESS_RATE\n        or payload.error_rate > PHASE6I_MAX_ERROR_RATE\n        or payload.availability < PHASE6I_MIN_AVAILABILITY\n    ):\n        status = "attention_required"\n\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "stage_number": payload.stage_number,\n        "success_rate": payload.success_rate,\n        "error_rate": payload.error_rate,\n        "availability": payload.availability,\n        "customer_count": payload.customer_count,\n        "notes": payload.notes.strip(),\n        "status": status,\n        "recorded_by": user.get("id", "unknown"),\n        "created_at": datetime.now().isoformat(),\n        "external_action_performed": False,\n    }\n    records = _phase6i_load(PHASE6I_OBSERVATIONS_FILE, [])\n    records.append(item)\n    _phase6i_save(PHASE6I_OBSERVATIONS_FILE, records[-30000:])\n    phase6h_append_event(\n        plan_id,\n        "observation_recorded",\n        user.get("id", "unknown"),\n        f"stage={payload.stage_number};status={status}",\n    )\n    return {"status": "complete", "observation": item}\n\n\n@app.post("/api/rollouts/{plan_id}/exceptions")\ndef phase6i_exception(plan_id: str, payload: Phase6IExceptionModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6h_plan_by_id(plan_id):\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "severity": payload.severity,\n        "category": payload.category.strip(),\n        "summary": payload.summary.strip(),\n        "owner": payload.owner.strip(),\n        "containment": payload.containment.strip(),\n        "status": "open",\n        "created_at": datetime.now().isoformat(),\n        "updated_at": datetime.now().isoformat(),\n        "created_by": user.get("id", "unknown"),\n    }\n    records = _phase6i_load(PHASE6I_EXCEPTIONS_FILE, [])\n    records.append(item)\n    _phase6i_save(PHASE6I_EXCEPTIONS_FILE, records[-20000:])\n    phase6h_append_event(\n        plan_id,\n        f"exception_{payload.severity}",\n        user.get("id", "unknown"),\n        payload.summary,\n    )\n    return {"status": "complete", "exception": item}\n\n\n@app.put("/api/rollouts/{plan_id}/exceptions/{exception_id}")\ndef phase6i_exception_status(\n    plan_id: str,\n    exception_id: str,\n    payload: Phase6IExceptionStatusModel,\n    request: Request,\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    records = _phase6i_load(PHASE6I_EXCEPTIONS_FILE, [])\n    item = next(\n        (\n            entry for entry in records\n            if entry.get("id") == exception_id and entry.get("plan_id") == plan_id\n        ),\n        None,\n    )\n    if not item:\n        raise HTTPException(status_code=404, detail="Rollout exception not found.")\n\n    item["status"] = payload.status\n    item["resolution_notes"] = payload.notes.strip()\n    item["updated_at"] = datetime.now().isoformat()\n    item["updated_by"] = user.get("id", "unknown")\n    _phase6i_save(PHASE6I_EXCEPTIONS_FILE, records)\n    phase6h_append_event(\n        plan_id,\n        f"exception_{payload.status}",\n        user.get("id", "unknown"),\n        exception_id,\n    )\n    return {"status": "complete", "exception": item}\n\n\n@app.post("/api/rollouts/{plan_id}/assurance-signoffs")\ndef phase6i_signoff(plan_id: str, payload: Phase6ISignoffModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6h_plan_by_id(plan_id):\n        raise HTTPException(status_code=404, detail="Rollout plan not found.")\n\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "plan_id": plan_id,\n        "decision": payload.decision,\n        "approver": payload.approver.strip(),\n        "role": payload.role.strip(),\n        "notes": payload.notes.strip(),\n        "created_at": datetime.now().isoformat(),\n        "recorded_by": user.get("id", "unknown"),\n    }\n    records = _phase6i_load(PHASE6I_SIGNOFFS_FILE, [])\n    records.append(item)\n    _phase6i_save(PHASE6I_SIGNOFFS_FILE, records[-10000:])\n    phase6h_append_event(\n        plan_id,\n        f"assurance_signoff_{payload.decision}",\n        user.get("id", "unknown"),\n        f"{payload.approver} ({payload.role})",\n    )\n    return {"status": "complete", "signoff": item}\n\n\n@app.get("/api/rollouts/{plan_id}/assurance")\ndef phase6i_assurance_api(plan_id: str, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    return phase6i_rollout_assurance(plan_id)\n\n\n@app.get("/rollout-assurance", response_class=HTMLResponse)\ndef phase6i_assurance_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    content = """\n    <header class="topbar">\n      <div><p class="eyebrow">Phase 6I</p><h1>Rollout assurance</h1></div>\n      <span class="pill">Observation only</span>\n    </header>\n    <section class="panel">\n      <div class="panel-head">\n        <div>\n          <h2>Post-launch assurance review</h2>\n          <div class="health-detail">Reviews locally recorded rollout observations, exceptions, and signoffs. It performs no deployment or rollback action.</div>\n        </div>\n      </div>\n      <label>Rollout plan ID<input id="p6i-plan-id" placeholder="Rollout plan ID"></label>\n      <div style="margin-top:12px">\n        <button class="action-button" id="p6i-review">Run assurance review</button>\n      </div>\n      <pre id="p6i-output" style="white-space:pre-wrap;margin-top:16px"></pre>\n    </section>\n    """\n    scripts = """\n    <script>\n    document.getElementById(\'p6i-review\').onclick=async()=>{\n      const id=document.getElementById(\'p6i-plan-id\').value.trim();\n      const response=await fetch(`/api/rollouts/${encodeURIComponent(id)}/assurance`);\n      const data=await response.json();\n      document.getElementById(\'p6i-output\').textContent=JSON.stringify(data,null,2);\n      if(!response.ok) showToast(data.detail||\'Assurance review failed.\');\n    };\n    </script>\n    """\n    return page_shell("Rollout assurance", "settings", content, scripts)\n'
PHASE6J_SOURCE = '\n# ============================================================================\n# Phase 6J — Service Transition, SLA Governance, and Operational Handoff\n# Local governance records only. No automatic ticketing, paging, deployment,\n# provider activation, or customer communication is performed.\n# ============================================================================\n\nPHASE6J_MARKER = "Phase 6J — Service Transition, SLA Governance, and Operational Handoff"\nPHASE6J_SERVICES_FILE = RECORDINGS_FOLDER / "phase6j_service_registry.json"\nPHASE6J_SLA_FILE = RECORDINGS_FOLDER / "phase6j_sla_policies.json"\nPHASE6J_HANDOFFS_FILE = RECORDINGS_FOLDER / "phase6j_operational_handoffs.json"\nPHASE6J_ESCALATIONS_FILE = RECORDINGS_FOLDER / "phase6j_escalation_matrix.json"\nPHASE6J_REVIEWS_FILE = RECORDINGS_FOLDER / "phase6j_transition_reviews.json"\n\nPHASE6J_REQUIRED_HANDOFFS = int(os.environ.get("PHASE6J_REQUIRED_HANDOFFS", "2"))\nPHASE6J_MAX_P1_RESPONSE_MINUTES = int(os.environ.get("PHASE6J_MAX_P1_RESPONSE_MINUTES", "15"))\nPHASE6J_MAX_P2_RESPONSE_MINUTES = int(os.environ.get("PHASE6J_MAX_P2_RESPONSE_MINUTES", "60"))\nPHASE6J_MIN_AVAILABILITY_TARGET = float(os.environ.get("PHASE6J_MIN_AVAILABILITY_TARGET", "99.0"))\n\n\nclass Phase6JServiceModel(BaseModel):\n    name: str = Field(min_length=3, max_length=160)\n    owner: str = Field(min_length=2, max_length=120)\n    description: str = Field(default="", max_length=3000)\n    support_hours: str = Field(min_length=3, max_length=200)\n    customer_scope: str = Field(min_length=2, max_length=1000)\n    dependencies: list[str] = Field(default_factory=list, max_length=50)\n\n\nclass Phase6JSLAModel(BaseModel):\n    availability_target: float = Field(ge=0, le=100)\n    p1_response_minutes: int = Field(ge=1, le=10080)\n    p2_response_minutes: int = Field(ge=1, le=10080)\n    restoration_target_minutes: int = Field(ge=1, le=10080)\n    measurement_window: str = Field(min_length=2, max_length=120)\n    exclusions: list[str] = Field(default_factory=list, max_length=50)\n\n\nclass Phase6JHandoffModel(BaseModel):\n    role: str = Field(min_length=2, max_length=120)\n    owner: str = Field(min_length=2, max_length=120)\n    decision: str = Field(pattern="^(accepted|rejected|revoked)$")\n    runbook_verified: bool\n    access_verified: bool\n    training_verified: bool\n    notes: str = Field(default="", max_length=3000)\n\n\nclass Phase6JEscalationModel(BaseModel):\n    severity: str = Field(pattern="^(p1|p2|p3|p4)$")\n    primary_contact: str = Field(min_length=2, max_length=160)\n    secondary_contact: str = Field(default="", max_length=160)\n    response_minutes: int = Field(ge=1, le=10080)\n    communication_channel: str = Field(min_length=2, max_length=160)\n    notes: str = Field(default="", max_length=2000)\n\n\ndef _phase6j_load(path: Path, default):\n    value = load_json_file(path, default)\n    return value if isinstance(value, type(default)) else default\n\n\ndef _phase6j_save(path: Path, value) -> None:\n    save_json_file(path, value)\n\n\ndef phase6j_service_by_id(service_id: str) -> dict | None:\n    return next(\n        (\n            item for item in _phase6j_load(PHASE6J_SERVICES_FILE, [])\n            if item.get("id") == service_id\n        ),\n        None,\n    )\n\n\ndef phase6j_transition_review(service_id: str) -> dict:\n    service = phase6j_service_by_id(service_id)\n    if not service:\n        raise HTTPException(status_code=404, detail="Service record not found.")\n\n    sla_records = [\n        item for item in _phase6j_load(PHASE6J_SLA_FILE, [])\n        if item.get("service_id") == service_id\n    ]\n    handoffs = [\n        item for item in _phase6j_load(PHASE6J_HANDOFFS_FILE, [])\n        if item.get("service_id") == service_id\n    ]\n    escalations = [\n        item for item in _phase6j_load(PHASE6J_ESCALATIONS_FILE, [])\n        if item.get("service_id") == service_id\n    ]\n\n    latest_sla = sla_records[-1] if sla_records else None\n\n    active_handoffs = {}\n    for item in handoffs:\n        key = (item.get("owner", "").lower(), item.get("role", "").lower())\n        if item.get("decision") == "accepted":\n            active_handoffs[key] = item\n        elif item.get("decision") in {"rejected", "revoked"}:\n            active_handoffs.pop(key, None)\n\n    latest_escalations = {}\n    for item in escalations:\n        latest_escalations[item.get("severity")] = item\n\n    blockers = []\n    if not latest_sla:\n        blockers.append("SLA policy has not been recorded.")\n    else:\n        if float(latest_sla.get("availability_target", 0)) < PHASE6J_MIN_AVAILABILITY_TARGET:\n            blockers.append("Availability target is below the Phase 6J minimum.")\n        if int(latest_sla.get("p1_response_minutes", 999999)) > PHASE6J_MAX_P1_RESPONSE_MINUTES:\n            blockers.append("P1 response time exceeds the Phase 6J maximum.")\n        if int(latest_sla.get("p2_response_minutes", 999999)) > PHASE6J_MAX_P2_RESPONSE_MINUTES:\n            blockers.append("P2 response time exceeds the Phase 6J maximum.")\n\n    if len(active_handoffs) < PHASE6J_REQUIRED_HANDOFFS:\n        blockers.append(f"{PHASE6J_REQUIRED_HANDOFFS} accepted operational handoffs are required.")\n\n    for key, item in active_handoffs.items():\n        if not (\n            item.get("runbook_verified")\n            and item.get("access_verified")\n            and item.get("training_verified")\n        ):\n            blockers.append(\n                f"Handoff verification is incomplete for {item.get(\'owner\', \'unknown\')}."\n            )\n\n    for severity in ("p1", "p2"):\n        if severity not in latest_escalations:\n            blockers.append(f"Escalation contact is missing for {severity.upper()}.")\n\n    assurance_records = _phase6i_load(PHASE6I_ASSURANCE_FILE, [])\n    latest_assurance = next(\n        (\n            item for item in reversed(assurance_records)\n            if item.get("assured") is True\n        ),\n        None,\n    )\n    if not latest_assurance:\n        blockers.append("No successful Phase 6I assurance review is available.")\n\n    review = {\n        "id": uuid.uuid4().hex[:16],\n        "service_id": service_id,\n        "checked_at": datetime.now().isoformat(),\n        "transition_ready": not blockers,\n        "service": service,\n        "latest_sla": latest_sla,\n        "accepted_handoff_count": len(active_handoffs),\n        "required_handoff_count": PHASE6J_REQUIRED_HANDOFFS,\n        "escalation_severities": sorted(latest_escalations.keys()),\n        "phase6i_assurance_reference": latest_assurance.get("id") if latest_assurance else None,\n        "blockers": blockers,\n        "automatic_action_performed": False,\n    }\n    reviews = _phase6j_load(PHASE6J_REVIEWS_FILE, [])\n    reviews.append(review)\n    _phase6j_save(PHASE6J_REVIEWS_FILE, reviews[-5000:])\n    structured_log(\n        "phase6j.transition_review",\n        service_id=service_id,\n        transition_ready=review["transition_ready"],\n        blocker_count=len(blockers),\n    )\n    return review\n\n\n@app.get("/api/service-transition/services")\ndef phase6j_list_services(request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    services = _phase6j_load(PHASE6J_SERVICES_FILE, [])\n    return {"services": list(reversed(services[-1000:]))}\n\n\n@app.post("/api/service-transition/services")\ndef phase6j_create_service(payload: Phase6JServiceModel, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    now = datetime.now().isoformat()\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "name": payload.name.strip(),\n        "owner": payload.owner.strip(),\n        "description": payload.description.strip(),\n        "support_hours": payload.support_hours.strip(),\n        "customer_scope": payload.customer_scope.strip(),\n        "dependencies": [item.strip() for item in payload.dependencies if item.strip()],\n        "status": "draft",\n        "created_at": now,\n        "updated_at": now,\n        "created_by": user.get("id", "unknown"),\n    }\n    records = _phase6j_load(PHASE6J_SERVICES_FILE, [])\n    records.append(item)\n    _phase6j_save(PHASE6J_SERVICES_FILE, records[-5000:])\n    return {\n        "status": "complete",\n        "message": "Service transition record created.",\n        "service": item,\n        "external_action_performed": False,\n    }\n\n\n@app.post("/api/service-transition/services/{service_id}/sla")\ndef phase6j_record_sla(\n    service_id: str, payload: Phase6JSLAModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6j_service_by_id(service_id):\n        raise HTTPException(status_code=404, detail="Service record not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "service_id": service_id,\n        "availability_target": payload.availability_target,\n        "p1_response_minutes": payload.p1_response_minutes,\n        "p2_response_minutes": payload.p2_response_minutes,\n        "restoration_target_minutes": payload.restoration_target_minutes,\n        "measurement_window": payload.measurement_window.strip(),\n        "exclusions": [value.strip() for value in payload.exclusions if value.strip()],\n        "created_at": datetime.now().isoformat(),\n        "recorded_by": user.get("id", "unknown"),\n    }\n    records = _phase6j_load(PHASE6J_SLA_FILE, [])\n    records.append(item)\n    _phase6j_save(PHASE6J_SLA_FILE, records[-10000:])\n    return {"status": "complete", "sla": item}\n\n\n@app.post("/api/service-transition/services/{service_id}/handoffs")\ndef phase6j_record_handoff(\n    service_id: str, payload: Phase6JHandoffModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6j_service_by_id(service_id):\n        raise HTTPException(status_code=404, detail="Service record not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "service_id": service_id,\n        "role": payload.role.strip(),\n        "owner": payload.owner.strip(),\n        "decision": payload.decision,\n        "runbook_verified": payload.runbook_verified,\n        "access_verified": payload.access_verified,\n        "training_verified": payload.training_verified,\n        "notes": payload.notes.strip(),\n        "created_at": datetime.now().isoformat(),\n        "recorded_by": user.get("id", "unknown"),\n    }\n    records = _phase6j_load(PHASE6J_HANDOFFS_FILE, [])\n    records.append(item)\n    _phase6j_save(PHASE6J_HANDOFFS_FILE, records[-10000:])\n    return {"status": "complete", "handoff": item}\n\n\n@app.post("/api/service-transition/services/{service_id}/escalations")\ndef phase6j_record_escalation(\n    service_id: str, payload: Phase6JEscalationModel, request: Request\n) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    if not phase6j_service_by_id(service_id):\n        raise HTTPException(status_code=404, detail="Service record not found.")\n    item = {\n        "id": uuid.uuid4().hex[:16],\n        "service_id": service_id,\n        "severity": payload.severity,\n        "primary_contact": payload.primary_contact.strip(),\n        "secondary_contact": payload.secondary_contact.strip(),\n        "response_minutes": payload.response_minutes,\n        "communication_channel": payload.communication_channel.strip(),\n        "notes": payload.notes.strip(),\n        "created_at": datetime.now().isoformat(),\n        "recorded_by": user.get("id", "unknown"),\n    }\n    records = _phase6j_load(PHASE6J_ESCALATIONS_FILE, [])\n    records.append(item)\n    _phase6j_save(PHASE6J_ESCALATIONS_FILE, records[-10000:])\n    return {"status": "complete", "escalation": item}\n\n\n@app.get("/api/service-transition/services/{service_id}/review")\ndef phase6j_review_api(service_id: str, request: Request) -> dict:\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n    return phase6j_transition_review(service_id)\n\n\n@app.get("/service-transition", response_class=HTMLResponse)\ndef phase6j_transition_page(request: Request):\n    user = current_user(request)\n    if not has_permission(user, "manage_settings"):\n        raise HTTPException(status_code=403, detail="Settings permission is required.")\n\n    content = """\n    <header class="topbar">\n      <div><p class="eyebrow">Phase 6J</p><h1>Service transition and SLA governance</h1></div>\n      <span class="pill">Manual handoff</span>\n    </header>\n    <section class="panel">\n      <div class="panel-head">\n        <div>\n          <h2>Operational transition review</h2>\n          <div class="health-detail">Reviews service ownership, SLA targets, handoffs, escalation contacts, and Phase 6I assurance. No ticket, page, email, or deployment is triggered.</div>\n        </div>\n      </div>\n      <label>Service ID<input id="p6j-service-id" placeholder="Service ID"></label>\n      <div style="margin-top:12px">\n        <button class="action-button" id="p6j-review">Run transition review</button>\n      </div>\n      <pre id="p6j-output" style="white-space:pre-wrap;margin-top:16px"></pre>\n    </section>\n    """\n    scripts = """\n    <script>\n    document.getElementById(\'p6j-review\').onclick=async()=>{\n      const id=document.getElementById(\'p6j-service-id\').value.trim();\n      const response=await fetch(`/api/service-transition/services/${encodeURIComponent(id)}/review`);\n      const data=await response.json();\n      document.getElementById(\'p6j-output\').textContent=JSON.stringify(data,null,2);\n      if(!response.ok) showToast(data.detail||\'Transition review failed.\');\n    };\n    </script>\n    """\n    return page_shell("Service transition", "settings", content, scripts)\n'

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def strip_previous(source: str) -> str:
    markers = (
        PHASE6E_MARKER,
        PHASE6F_MARKER,
        PHASE6G_MARKER,
        PHASE6H_MARKER,
        PHASE6I_MARKER,
        PHASE6J_MARKER,
    )
    positions = [position for marker in markers if (position := source.find(marker)) >= 0]
    return source[:min(positions)].rstrip() if positions else source.rstrip()

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("target", nargs="?", default="app/main.py")
    args = parser.parse_args()
    target = Path(args.target).expanduser().resolve()

    if not target.exists():
        print(f"ERROR: target not found: {target}", file=sys.stderr)
        return 2

    original_bytes = target.read_bytes()
    null_count = original_bytes.count(b"\x00")
    if null_count:
        print(f"ERROR: target contains {null_count} null bytes.", file=sys.stderr)
        return 3

    original = original_bytes.decode("utf-8")
    ast.parse(original)

    combined = (
        strip_previous(original)
        + "\n\n" + PHASE6E_SOURCE.strip()
        + "\n\n" + PHASE6F_SOURCE.strip()
        + "\n\n" + PHASE6G_SOURCE.strip()
        + "\n\n" + PHASE6H_SOURCE.strip()
        + "\n\n" + PHASE6I_SOURCE.strip()
        + "\n\n" + PHASE6J_SOURCE.strip()
        + "\n"
    )
    ast.parse(combined)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = target.with_name(f"{target.stem}_before_phase6j_{stamp}{target.suffix}")
    shutil.copy2(target, backup)
    target.write_text(combined, encoding="utf-8")

    sums = target.with_name("SHA256SUMS")
    sums.write_text(
        f"{sha256(target)}  {target.name}\n{sha256(backup)}  {backup.name}\n",
        encoding="utf-8",
    )

    print("Phase 6J override complete.")
    print(f"Updated: {target}")
    print(f"Backup: {backup}")
    print(f"SHA256SUMS: {sums}")
    print(f"Updated SHA-256: {sha256(target)}")
    print("Automatic ticketing, paging, deployment, or customer communication performed: no")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
